#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

static const uint16_t CW_EXCEL = 0x133F;
static const double MIN_POS = 2.2250738585072014e-308;

static inline void set_cw(uint16_t cw) { __asm__ volatile ("fldcw %0" : : "m"(cw)); }
static inline uint16_t get_cw(void) { uint16_t cw; __asm__ volatile ("fnstcw %0" : "=m"(cw)); return cw; }
static inline double st64(long double x) { volatile double d = (double)x; return d; }

static inline double x87_add(double a, double b) {
    volatile long double la = a, lb = b;
    return st64(la + lb);
}
static inline double x87_sub(double a, double b) {
    volatile long double la = a, lb = b;
    return st64(la - lb);
}
static inline double x87_mul(double a, double b) {
    volatile long double la = a, lb = b;
    return st64(la * lb);
}
static inline double x87_div(double a, double b) {
    volatile long double la = a, lb = b;
    return st64(la / lb);
}

static inline double irr_daz(double v) {
    return (fabs(v) < MIN_POS) ? copysign(0.0, v) : v;
}
static inline double irr_ftz(double v) {
    return (fabs(v) < MIN_POS) ? 0.0 : v;
}
static inline uint64_t f2u(double x) {
    if (x == 0.0) x = 0.0;
    uint64_t u;
    memcpy(&u, &x, 8);
    return u;
}

#define ERR_NUM   0xFFFFFFFFFFFFFFF1ULL
#define ERR_VALUE 0xFFFFFFFFFFFFFFF2ULL
#define ERR_DIV0  0xFFFFFFFFFFFFFFF3ULL

static int master_npv(const double *flows, int n, double u, double *out) {
    double v = x87_sub(1.0, u);
    if (v == 0.0) return 0;
    double base = x87_div(1.0, v);
    if (!isfinite(base) || base == 0.0) return 0;
    double total = 0.0;
    double power = 1.0;
    for (int k = 0; k < n; k++) {
        if (k > 0) power = x87_mul(power, base);
        double divisor = irr_daz(power);
        if (!isfinite(divisor) || divisor == 0.0) return 0;
        double term = irr_daz(x87_div(flows[k], divisor));
        if (!isfinite(term)) return 0;
        total = x87_add(total, term);
    }
    if (!isfinite(total)) return 0;
    *out = total;
    return 1;
}

static int master_publish(double u, double *rate_out) {
    double v = x87_sub(1.0, u);
    if (v <= 0.0) return 0;
    double rate = x87_sub(x87_div(1.0, v), 1.0);
    if (isfinite(rate) && rate > -1.0) {
        *rate_out = rate;
        return 1;
    }
    return 0;
}

static int master_secant(const double *flows, int n, double u_start, double *rate_out) {
    if (!isfinite(u_start)) return 0;
    double before = u_start, value_before;
    if (!master_npv(flows, n, before, &value_before)) return 0;
    double offset = (value_before > 0.0) ? -0.001 : 0.001;
    double current = x87_add(before, offset), value;
    if (!master_npv(flows, n, current, &value)) return 0;
    double step = INFINITY;
    for (int iter = 0; iter < 200; iter++) {
        double change = x87_sub(value, value_before);
        if (change == 0.0) {
            double nudge = (current > before) ? 0.001 : -0.001;
            before = x87_add(before, nudge);
            if (!master_npv(flows, n, before, &value_before)) return 0;
            change = x87_sub(value, value_before);
            if (change == 0.0) continue;
        }
        double divisor = irr_daz(change);
        if (divisor == 0.0) return 0;
        double numerator = irr_daz(x87_mul(value, x87_sub(current, before)));
        double next = x87_sub(current, x87_div(numerator, divisor));
        if (!isfinite(next)) return 0;
        step = fabs(x87_sub(next, current));
        before = current;
        value_before = value;
        current = next;
        if (!master_npv(flows, n, current, &value)) return 0;
        if (step < 1e-7 && fabs(value) < 1e-7) {
            return master_publish(current, rate_out);
        }
    }
    if (step <= 1e-4 && fabs(value) <= 1e-4) {
        return master_publish(current, rate_out);
    }
    return 0;
}

uint64_t eval_irr_master(const double *flows, int n, int has_guess, double guess) {
    uint16_t old_cw = get_cw();
    set_cw(CW_EXCEL);
    double g = has_guess ? guess : 0.1;
    if (isfinite(g) && (g <= -1.0 || x87_add(1.0, g) == g)) {
        set_cw(old_cw);
        return ERR_VALUE;
    }
    if (n < 2) { set_cw(old_cw); return ERR_NUM; }
    int has_pos = 0, has_neg = 0;
    for (int i = 0; i < n; i++) {
        if (!isfinite(flows[i])) { set_cw(old_cw); return ERR_VALUE; }
        if (flows[i] > 0.0) has_pos = 1;
        if (flows[i] < 0.0) has_neg = 1;
    }
    if (!has_pos || !has_neg) { set_cw(old_cw); return ERR_NUM; }

    double r;
    double u_guess = x87_div(g, x87_add(1.0, g));
    if (master_secant(flows, n, u_guess, &r)) { r = irr_ftz(r); set_cw(old_cw); return f2u(r); }
    if (g != 0.1 && master_secant(flows, n, x87_div(0.1, x87_add(1.0, 0.1)), &r)) { r = irr_ftz(r); set_cw(old_cw); return f2u(r); }
    if (master_secant(flows, n, -0.1, &r)) { r = irr_ftz(r); set_cw(old_cw); return f2u(r); }
    if (master_secant(flows, n, x87_div(2.0, 3.0), &r)) { r = irr_ftz(r); set_cw(old_cw); return f2u(r); }
    set_cw(old_cw);
    return ERR_NUM;
}

double decimal_scale_15_c(double coeff) {
    uint16_t o = get_cw(); set_cw(CW_EXCEL);
    long double rec = 1.0L / 1000000000000000.0L;
    double out = st64((long double)coeff * rec);
    set_cw(o); return out;
}

