def excel_parse_text_num(s):
    txt = s.replace("\u00a0", " ").strip()
    if not txt: return None
    m = re.fullmatch(r"([+-]?)\s*(\d+(?:\.\d*)?|\.\d+)(?:[eE]([+-]?\d+))?", txt)
    if not m: return None
    sgn, mant, exp_s = m.group(1), m.group(2), m.group(3)
    exp10 = int(exp_s) if exp_s else 0
    if "." in mant:
        ip, fp = mant.split(".")
        digits = (ip + fp).lstrip("0")
        exp10 -= len(fp)
    else:
        digits = mant.lstrip("0")
    if not digits: return 0.0
    if len(digits) > 15:
        exp10 += len(digits) - 15
        digits = digits[:15]
    coeff = float(int(digits))
    if exp10 == -15: val = lib.decimal_scale_15_c(coeff)
    elif -15 < exp10 < 0: val = lib.decimal_scale_15_c(coeff * (10.0 ** (15 + exp10)))
    else: val = float(f"{digits}e{exp10}")
