static const uint16_t CW_EXCEL = 0x133F;
static const double MIN_POS = 2.2250738585072014e-308;

static inline void set_cw(uint16_t cw) { __asm__ volatile ("fldcw %0" : : "m"(cw)); }
static inline uint16_t get_cw(void) { uint16_t cw; __asm__ volatile ("fnstcw %0" : "=m"(cw)); return cw; }
static inline double st64(long double x) { volatile double d = (double)x; return d; }

static inline double x87_add(double a, double b) { volatile long double la = a, lb = b; return st64(la + lb); }
static inline double x87_sub(double a, double b) { volatile long double la = a, lb = b; return st64(la - lb); }
static inline double x87_mul(double a, double b) { volatile long double la = a, lb = b; return st64(la * lb); }
static inline double x87_div(double a, double b) { volatile long double la = a, lb = b; return st64(la / lb); }

static inline double irr_daz(double v) { return (fabs(v) < MIN_POS) ? copysign(0.0, v) : v; }
static inline double irr_ftz(double v) { return (fabs(v) < MIN_POS) ? 0.0 : v; }
static inline uint64_t f2u(double x) { if (x == 0.0) x = 0.0; uint64_t u; memcpy(&u, &x, 8); return u; }

#define ERR_NUM   0xFFFFFFFFFFFFFFF1ULL
#define ERR_VALUE 0xFFFFFFFFFFFFFFF2ULL
#define ERR_DIV0  0xFFFFFFFFFFFFFFF3ULL

/*
 Status codes from npv / secant:
   0 = OK (converged)
   1 = RETRYABLE_NUM
   2 = HARD_NUM (abort retry ladder, return #NUM!)
   3 = HARD_DIV0 (abort retry ladder, return #DIV/0!)
*/
typedef struct {
    int strip_lz;        // 1 = strip leading 0.0s
    int sign_check;      // 0 = no sign check (only n>=1 or n>=2 after strip?), 1 = master sign check
    int min_len_after;   // 1 or 2
    int pow_inf_mode;    // 0 = allow +inf power (flow/+inf = 0), 1 = retryable num, 2 = hard num, 3 = hard div0
    int pow_zero_mode;   // 3 = hard div0, 1 = retryable num
    int term_inf_mode;   // 1 = retryable num, 2 = hard num, 3 = hard div0
    int tot_inf_mode;    // 1 = retryable num, 2 = hard num
    int v_zero_mode;     // 3 = hard div0, 1 = retryable num
    int flat_mode;       // 0 = master (change==0, >, continue), 1 = rate_cb22 (change==0, >=, double-flat->retry), 2 = rate_flat_change (-MIN_POS/16..0, >=, double-flat->retry)
    int sec_div0_mode;   // when daz(change)==0: 3 = hard div0, 1 = retryable num
    int next_inf_mode;   // when !isfinite(next): 1 = retryable num, 2 = hard num, 3 = hard div0 (if divisor small)
    int pub_v_mode;      // 0 = v>0, 1 = v>=1e-7 always, 2 = v>=1e-7 in-loop & v>=1e-4 post-loop, 3 = v>1e-7 always, 4 = r<=1e7-1
    int step0_guard;     // 0 = none, 1 = require change != 0 / something on [-DBL_MAX, DBL_MAX]
} IrrCfg;

static int cand_npv(const double *flows, int n, double u, const IrrCfg *cfg, double *out) {
    double v = x87_sub(1.0, u);
    if (v == 0.0) return cfg->v_zero_mode;
    double base = x87_div(1.0, v);
    if (!isfinite(base)) return 1;
    if (base == 0.0) return cfg->pow_zero_mode;
    double total = 0.0;
    double power = 1.0;
    for (int k = 0; k < n; k++) {
        if (k > 0) power = x87_mul(power, base);
        double divisor = irr_daz(power);
        if (divisor == 0.0) return cfg->pow_zero_mode;
        if (!isfinite(divisor)) {
            if (cfg->pow_inf_mode != 0) return cfg->pow_inf_mode;
            // allow divisor = ±inf: flows[k] / ±inf = 0.0 (unless flows[k] is inf, already checked)
        }
        double term = irr_daz(x87_div(flows[k], divisor));
        if (!isfinite(term)) return cfg->term_inf_mode;
        total = x87_add(total, term);
        if (!isfinite(total)) return cfg->tot_inf_mode;
    }
    *out = total;
    return 0;
}

static int cand_publish(double u, int is_post, const IrrCfg *cfg, double *rate_out) {
    double v = x87_sub(1.0, u);
    if (cfg->pub_v_mode == 0) {
        if (v <= 0.0) return 1;
    } else if (cfg->pub_v_mode == 1) {
        if (v < 1e-7) return 1;
    } else if (cfg->pub_v_mode == 2) {
        if (v < (is_post ? 1e-4 : 1e-7)) return 1;
    } else if (cfg->pub_v_mode == 3) {
        if (v <= 1e-7) return 1;
    }
    double rate = x87_sub(x87_div(1.0, v), 1.0);
    if (!isfinite(rate) || rate <= -1.0) return 1;
    if (cfg->pub_v_mode == 4 && x87_add(1.0, rate) > 1e7) return 1;
    *rate_out = rate;
    return 0;
}

static inline int is_flat(double change, int flat_mode) {
    if (flat_mode == 2) return (change > -MIN_POS / 16.0 && change <= 0.0);
    return (change == 0.0);
}

static int cand_secant(const double *flows, int n, double u_start, const IrrCfg *cfg, double *rate_out) {
    if (!isfinite(u_start)) return 1;
    double before = u_start, value_before;
    int st = cand_npv(flows, n, before, cfg, &value_before);
    if (st != 0) return st;
    double offset = (value_before > 0.0) ? -0.001 : 0.001;
    double current = x87_add(before, offset), value;
    st = cand_npv(flows, n, current, cfg, &value);
    if (st != 0) return st;
    double step = INFINITY;
    for (int iter = 0; iter < 200; iter++) {
        double change = x87_sub(value, value_before);
        if (is_flat(change, cfg->flat_mode)) {
            double nudge = (cfg->flat_mode == 0)
                ? ((current > before) ? 0.001 : -0.001)
                : ((current >= before) ? 0.001 : -0.001);
            before = x87_add(before, nudge);
            st = cand_npv(flows, n, before, cfg, &value_before);
            if (st != 0) return st;
            change = x87_sub(value, value_before);
            if (is_flat(change, cfg->flat_mode)) {
                if (cfg->flat_mode == 0) continue;
                return 1; // retryable failure!
            }
        }
        double divisor = irr_daz(change);
        if (divisor == 0.0) return cfg->sec_div0_mode;
        double numerator = irr_daz(x87_mul(value, x87_sub(current, before)));
        if (!isfinite(numerator) && cfg->step0_guard == 1) return 1;
        double quo = x87_div(numerator, divisor);
        if (!isfinite(quo) && cfg->next_inf_mode == 2) return 2;
        double next = x87_sub(current, quo);
        if (!isfinite(next)) return (cfg->next_inf_mode == 2) ? 2 : 1;
        step = fabs(x87_sub(next, current));
        before = current;
        value_before = value;
        current = next;
        st = cand_npv(flows, n, current, cfg, &value);
        if (st != 0) return st;
        if (step < 1e-7 && fabs(value) < 1e-7) {
            return cand_publish(current, 0, cfg, rate_out);
        }
    }
    if (step <= 1e-4 && fabs(value) <= 1e-4) {
        return cand_publish(current, 1, cfg, rate_out);
    }
    return 1;
}

uint64_t eval_irr_cand(const double *flows_in, int n_in, int has_guess, double guess, const IrrCfg *cfg) {
    uint16_t old_cw = get_cw();
    set_cw(CW_EXCEL);
    double g = has_guess ? guess : 0.1;
    if (isfinite(g) && (g <= -1.0 || x87_add(1.0, g) == g)) {
        set_cw(old_cw);
        return ERR_VALUE;
    }
    for (int i = 0; i < n_in; i++) {
        if (!isfinite(flows_in[i])) { set_cw(old_cw); return ERR_VALUE; }
    }
    if (n_in < 1) { set_cw(old_cw); return ERR_NUM; }
    int start = 0;
    if (cfg->strip_lz) {
        while (start < n_in && flows_in[start] == 0.0) start++;
    }
    const double *flows = flows_in + start;
    int n = n_in - start;
    if (n < cfg->min_len_after) { set_cw(old_cw); return ERR_NUM; }

    if (cfg->sign_check) {
        int hp = 0, hn = 0;
        for (int i = 0; i < n; i++) {
            if (flows[i] > 0.0) hp = 1;
            if (flows[i] < 0.0) hn = 1;
        }
        if (!hp || !hn) { set_cw(old_cw); return ERR_NUM; }
    }

    double tries[4];
    int nt = 0;
    tries[nt++] = x87_div(g, x87_add(1.0, g));
    if (g != 0.1) tries[nt++] = x87_div(0.1, x87_add(1.0, 0.1));
    tries[nt++] = -0.1;
    tries[nt++] = x87_div(2.0, 3.0);

    for (int t = 0; t < nt; t++) {
        double r;
        int st = cand_secant(flows, n, tries[t], cfg, &r);
        if (st == 0) {
            r = irr_ftz(r);
            set_cw(old_cw);
            return f2u(r);
        }
        if (st == 3) { set_cw(old_cw); return ERR_DIV0; }
        if (st == 2) { set_cw(old_cw); return ERR_NUM; }
    }
    set_cw(old_cw);
    return ERR_NUM;
}

