static const uint16_t CW_EXCEL = 0x133F;
static const double MIN_POS = 2.225073858585072014e-308; // wait: exact 0x0010000000000000 below!

static inline void set_cw(uint16_t cw) { __asm__ volatile ("fldcw %0" : : "m"(cw)); }
static inline uint16_t get_cw(void) { uint16_t cw; __asm__ volatile ("fnstcw %0" : "=m"(cw)); return cw; }
static inline double st64(long double x) { volatile double d = (double)x; return d; }

static inline double x87_add(double a, double b) { volatile long double la = a, lb = b; return st64(la + lb); }
static inline double x87_sub(double a, double b) { volatile long double la = a, lb = b; return st64(la - lb); }
static inline double x87_mul(double a, double b) { volatile long double la = a, lb = b; return st64(la * lb); }
static inline double x87_div(double a, double b) { volatile long double la = a, lb = b; return st64(la / lb); }

static inline uint64_t f2u(double x) { if (x == 0.0) x = 0.0; uint64_t u; memcpy(&u, &x, 8); return u; }
static inline double u2f(uint64_t u) { double x; memcpy(&x, &u, 8); return x; }

static inline double irr_daz(double v) {
    double mp = u2f(0x0010000000000000ULL);
    return (fabs(v) < mp) ? copysign(0.0, v) : v;
}
static inline double irr_ftz(double v) {
    double mp = u2f(0x0010000000000000ULL);
    return (fabs(v) < mp) ? 0.0 : v;
