     0: origin/master: flat=(-mp/16, 0]; div=daz(chg); if div==0 -> Div0; num=ftz(raw_num); quo=num/div; ovf_limit on !isfinite(quo)
     1: NO daz on chg, NO ftz on raw_num (pure x87 quo = raw_num / chg!), flat=(chg == 0.0)! Wait: if chg==0 -> nudge!
     2: flat=(-mp/16, 0]; NO daz on chg, NO ftz on raw_num: Wait - when does Div0 happen?!
     3: flat=(-mp/16, 0]; div=daz(chg); num=ftz(raw_num); IF div==0: check ovf_limit FIRST (if current>0 && nper<0 && |limit|<=1e-7 return current!), ELSE Div0!
     4: flat=(-mp/16, 0]; div=daz(chg); num=daz(raw_num); IF div==0 && num==0 && |value|<1e-7 -> return current! Wait: test!
     5: pure x87 balance (bal_ftz) + check what happens at div==0: record cur_at_div0!
*/

static int rate_bal_mode(double r, double nper, double pmt, double pv, double fv, int beg, int bal_ftz, double *out) {
    double factor, term;
    if (r == 0.0) {
        factor = 1.0;
        term = nper;
    } else {
        double base = x87_add(1.0, r);
        int perr = 0;
        factor = power_kernel_c(base, nper, 0, &perr);
        if (perr != 0) return perr;
        if (!isfinite(factor)) return 1;
        double raw_et = x87_div(x87_sub(factor, 1.0), r);
        double end_term = (bal_ftz == 0) ? raw_et : ftz(raw_et);
        double tf = beg ? x87_add(1.0, r) : 1.0;
        term = x87_mul(end_term, tf);
    }
    double pc = x87_mul(pv, factor);
    double mc = x87_mul(pmt, term);
    if (bal_ftz == 2) { pc = ftz(pc); mc = ftz(mc); }
    double pb = x87_add(pc, mc);
    if (bal_ftz == 2 || bal_ftz == 3) pb = ftz(pb);
    double total = x87_add(pb, fv);
    if (!isfinite(total)) return 1;
    *out = total;
    return 0;
}

uint64_t eval_rate_param(double nper, double pmt, double pv, double fv, int beg, int has_guess, double guess,
                         int bal_ftz, int div_mode, uint64_t *cur_at_div0_out) {
    if (cur_at_div0_out) *cur_at_div0_out = 0;
