    if (g <= -1.0) return ERR_VALUE;
    double before = g, value_before;
    int st = rate_bal_mode(before, nper, pmt, pv, fv, beg, bal_ftz, &value_before);
    if (st != 0) return 0xFFFFFFFFFFFFFFF0ULL + (uint64_t)st;
    double offset = (value_before > 0.0) ? -0.001 : 0.001;
    double current = x87_add(before, offset), value;
    st = rate_bal_mode(current, nper, pmt, pv, fv, beg, bal_ftz, &value);
    if (st != 0) return 0xFFFFFFFFFFFFFFF0ULL + (uint64_t)st;
    double step = INFINITY;
    double neg_cut = -MIN_POS / 16.0;

    for (int iter = 0; iter < 200; iter++) {
        double change = x87_sub(value, value_before);
        int is_flat = (div_mode == 1) ? (change == 0.0) : (change > neg_cut && change <= 0.0);
        if (is_flat) {
            double nudge = (current >= before) ? 0.001 : -0.001;
