        double divisor = (div_mode == 1) ? change : daz(change);
        double raw_num = x87_mul(value, x87_sub(current, before));
        double numerator = (div_mode == 1) ? raw_num : ftz(raw_num);

        if (divisor == 0.0) {
            if (cur_at_div0_out) {
                double rc = ftz(current); if (rc == 0.0) rc = 0.0;
                *cur_at_div0_out = f2u(rc);
            }
            if (div_mode == 3) {
                if (isfinite(current) && current > 0.0 && nper < 0.0) {
                    double raw_et = x87_div(-1.0, current);
                    double end_term_inf = (bal_ftz == 0) ? raw_et : ftz(raw_et);
                    double tf = beg ? x87_add(1.0, current) : 1.0;
                    double term_inf = x87_mul(end_term_inf, tf);
                    double mc = x87_mul(pmt, term_inf);
                    if (bal_ftz >= 2) mc = ftz(mc);
                    double limit = x87_add(mc, fv);
                    if (fabs(limit) <= 1e-7) {
                        if (x87_add(1.0, current) < 1e-7) return ERR_NUM;
                        double r = ftz(current); if (r == 0.0) r = 0.0; return f2u(r);
                    }
                }
            }
            return ERR_DIV0;
        }
        double quo = x87_div(numerator, divisor);
        if (!isfinite(quo) && isfinite(current) && current > 0.0 && nper < 0.0) {
            double raw_et = x87_div(-1.0, current);
            double end_term_inf = (bal_ftz == 0) ? raw_et : ftz(raw_et);
            double tf = beg ? x87_add(1.0, current) : 1.0;
            double term_inf = x87_mul(end_term_inf, tf);
            double mc = x87_mul(pmt, term_inf);
            if (bal_ftz >= 2) mc = ftz(mc);
            double limit = x87_add(mc, fv);
            if (fabs(limit) <= 1e-7) {
                if (x87_add(1.0, current) < 1e-7) return ERR_NUM;
                double r = ftz(current); if (r == 0.0) r = 0.0; return f2u(r);
            }
        }
        double next = x87_sub(current, quo);
        if (!isfinite(next)) return ERR_NUM;
        step = fabs(x87_sub(next, current));
        before = current;
        value_before = value;
        current = next;
        st = rate_bal_mode(current, nper, pmt, pv, fv, beg, bal_ftz, &value);
        if (st != 0) return 0xFFFFFFFFFFFFFFF0ULL + (uint64_t)st;
        if (step < 1e-7 && fabs(value) < 1e-7) {
            if (x87_add(1.0, current) < 1e-7) return ERR_NUM;
            double r = ftz(current); if (r == 0.0) r = 0.0; return f2u(r);
        }
    }
    if (step <= 1e-4 && fabs(value) <= 1e-4 && x87_add(1.0, current) >= 1e-4) {
        if (x87_add(1.0, current) < 1e-7) return ERR_NUM;
        double r = ftz(current); if (r == 0.0) r = 0.0; return f2u(r);
    }
    return ERR_NUM;
}
"""

