def parse_eu(s):
    s = str(s).strip()
    if s in ("Num", "#NUM!", "error:Num"): return 0xFFFFFFFFFFFFFFF1
    if s in ("Value", "#VALUE!", "error:Value"): return 0xFFFFFFFFFFFFFFF2
    if s in ("Div0", "#DIV/0!", "error:Div0"): return 0xFFFFFFFFFFFFFFF3
    if s.startswith("error:") or s.startswith("#"): return 0xFFFFFFFFFFFFFFF4
    return int(s.removeprefix("0x"), 16)


